import textstat

def check_message(text: str) -> dict:
    """Return readability scores for a draft message."""
    return {
        "flesch_reading_ease": textstat.flesch_reading_ease(text),
        "grade_level": textstat.flesch_kincaid_grade(text),
        "syllables_per_word": textstat.avg_syllables_per_word(text),
    }

if __name__ == "__main__":
    draft = "Get vaccinated by Friday to stay protected this winter."
    scores = check_message(draft)
    print(scores)
